import json
from pathlib import Path
base=Path(__file__).resolve().parents[1]
sectors={s['id']:s for f in (base/'seeds').glob('*.json') for s in json.load(open(f))}
activities=[a for a in json.load(open(base/'company_rules/observed_activities.json')) if int(a['okved'].split('.')[0])<40]
# Ручной подбор допустимых объектов; номера объектов относятся к существующим seeds (1-based).
rows={a['okved']:{'okved':a['okved'],'activity':a['activity'],'mappings':[],'unmapped_reason':None} for a in activities}
def add(codes,sector,indices,relation,reason,signals=None):
 sid=('industry_' if isinstance(sector,int) else '')+(f'{sector:02}' if isinstance(sector,int) else sector)
 names=[x['name'] for x in sectors[sid]['objects']]
 selected=names if indices=='all' else [names[i-1] for i in indices]
 for code in codes.split():
  rows[code]['mappings'].append(dict(sector_id=sid,objects=selected,relation=relation,reason=reason,signal_names=signals or []))
def gap(codes,reason):
 for c in codes.split():rows[c]['unmapped_reason']=reason
